-- ============================================================
-- 从 private_files/students_list.xlsx 生成的学生账号导入脚本
-- 规则：账号 = 姓名拼音小写 + 年级4位 + 班级2位 + 学号2位，密码 123456
-- 【执行前】请备份数据库；会删除原有学生、班级及学生相关学习记录（保留 admin、teacher1）
-- 在 Navicat：新建查询 -> 粘贴本文件全文 -> 运行
-- ============================================================

SET NAMES utf8mb4;
USE learn_space;

-- 清理学生相关数据（顺序避免外键/脏数据）
DELETE FROM learn_submission WHERE student_id IN (SELECT id FROM sys_user WHERE role = 'STUDENT');
DELETE FROM learn_progress WHERE student_id IN (SELECT id FROM sys_user WHERE role = 'STUDENT');
DELETE FROM learn_visit_log WHERE student_id IN (SELECT id FROM sys_user WHERE role = 'STUDENT');
DELETE FROM learn_points WHERE student_id IN (SELECT id FROM sys_user WHERE role = 'STUDENT');
DELETE FROM sys_class_student;
DELETE FROM sys_user WHERE role = 'STUDENT';
DELETE FROM sys_class;

ALTER TABLE sys_class AUTO_INCREMENT = 1;


-- 共 664 名学生

-- 班级学生关联（便于后续扩展）
SELECT u.class_id, u.id FROM sys_user u WHERE u.role = 'STUDENT' AND u.class_id IS NOT NULL;
